# Own-wording items of Dark Matter (2024), chunk A: baseitems (weapons, armor, gear) and the items from AI Core up to Embedded Armor.
# Row shape as tghp_item.py: add(name, type, rarity, attune, text, **opts). Gear rows: [name, cost gp, weight lb, type, text].
# Weapon stats come from the source baseitems. This file adds mastery texts (MASTERY) and property notes (WDESC).
ITEMS = []; SP = {}; WPN = {}; GEAR = []

def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

# ---- the 7 masteries of the book (own wording). Jolt and Shift are used by four weapons here and are written again so every mastery has its text.
MASTERY = {
 "Automatic": "When you attack with this weapon, you can make two attacks instead of one. Both have Disadvantage, whatever the circumstances, and neither can be swapped for something else. If the weapon has the Ammunition property, the pair uses twice the usual ammunition.",
 "Bludgeon": "You can treat this weapon as a Melee weapon with the Finesse property. A melee hit with it deals Bludgeoning damage equal to 1d6 plus the ability modifier of the attack, or 1d8 if you swing it with two hands.",
 "Explode": "When you take the Attack action, you can swap one attack for an explosion of the weapon's projectile. It is a 5-ft-radius Sphere at a point within normal range. Each creature in it makes a Dexterity save (DC 8 plus your Strength or Dexterity modifier plus your Proficiency Bonus). On a fail it takes the weapon's damage, without your ability modifier unless that modifier is negative. On a success it takes half. Only one explosion per turn.",
 "Mounted": "Bonus Action: fix the weapon in place until the end of your turn. While it is mounted, ranged attacks with it deal the damage shown in parentheses, and it cannot be moved.",
 "Overheat": "When you hit a target with this weapon, you can overcharge it. The target takes extra damage of the weapon's type equal to your Proficiency Bonus, and the weapon Overheats. An Overheated weapon cannot attack again until the end of your next turn.",
 "Scatter": "Being within 5 ft of an enemy does not impose Disadvantage on your ranged attack rolls with this weapon.",
 "Sighted": "Attacking at long range with this weapon does not impose Disadvantage. When you hit at long range, you can reroll any of the damage dice and must keep the new roll.",
 "Jolt": "A creature you hit with this weapon cannot make Opportunity Attacks until the start of its next turn.",
 "Shift": "When you hit a creature with this weapon, you can move 10 ft right away without provoking Opportunity Attacks.",
}

# ---- property notes. The five Dark Matter weapon properties have no field in the app, so each weapon lists the ones it has.
_B = "Blaster: a ranged weapon that needs no ammunition (it counts as having Ammunition)."
_F = "Firearm: do not add your ability modifier to its damage unless a rule says so. Ammunition is destroyed when used."
_C = "Cooldown: you can fire it only once per action, Bonus Action or Reaction, however many attacks you normally make (it counts as Loading)."
_R = "Recoil: after you attack with it, you cannot make ranged attacks beyond the weapon's normal range until the end of your turn."
_D = "Destructible: the weapon is destroyed after you attack with it."
WDESC = {
 "Antimatter Carbine": " ".join([_B, _F]),
 "Antimatter Pistol": " ".join([_B, _F]),
 "Avia-Ra Sunstaff": " ".join([_B, _F]) + " Its Bludgeon mastery lets you strike with it in melee, like a quarterstaff.",
 "Blitz Cannon": " ".join([_B, _F, _R]),
 "Bolt Caster": " ".join([_B, _C, _F]),
 "Bomb": "Finesse and Thrown. " + _D + " Its Explode mastery turns the attack into a blast.",
 "Concussion Rifle": " ".join([_B, _F, _R]) + " Heavy and Two-Handed.",
 "Dueling Laser": " ".join([_B, _F, _C]) + " Its Bludgeon mastery lets you strike with it in melee.",
 "Hardlight Dart": "A magical projectile that shatters and fades a few seconds after it hits. " + _D,
 "Ion Cannon": " ".join([_B, _C, _F, _R]),
 "Magnus": " ".join([_B, _F, _C]) + " Heavy.",
 "Phaser": " ".join([_B, _F]),
 "Plasma Launcher": " ".join([_B, _F, _C]) + "",
 "REC Gun": " ".join([_B, _F]) + " Heavy and Two-Handed. Mounted (2d8): when mounted it deals 2d8 on ranged attacks.",
 "Repeater": " ".join([_B, _F]),
 "Standard Carbine": " ".join([_B, _F]),
 "Swarm Pistol": " ".join([_B, _F]),
}

